CREATE OR REPLACE FUNCTION public.esports_answer_exam(p_attempt uuid, p_action text, p_expected integer, p_answers jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 declare a private.esports_attempts;
 begin
 select * into a from private.esports_attempts where id=p_attempt for update;
 if not found or a.user_id is distinct from auth.uid() or not private.esports_trial(a.application_id) then raise exception 'Attempt unavailable';end if;
 if a.status='active' and not exists(select 1 from private.esports_exam_assignments where application_id=a.application_id and exam_id=a.exam_id and revoked_at is null) then raise exception 'Assignment revoked';end if;
 if p_action not in('save','submit','timeout') or p_action is null then raise exception 'Unknown exam action';end if;
 if a.status<>'active' then return private.esports_safe_attempt(a.id);end if;
 if now()>=a.deadline then perform private.esports_finish_attempt(a.id);return private.esports_safe_attempt(a.id);end if;
 if p_action='timeout' then raise exception 'Deadline not reached';end if;
 if a.version<>p_expected then raise exception 'Version conflict';end if;
 perform private.esports_validate_answers(a.questions,p_answers);
 if (select count(*) from private.esports_audit where actor_id=auth.uid() and action='exam_saved' and created_at>now()-interval '1 minute')>=30 then raise exception 'Save rate limit';end if;
 update private.esports_attempts set answers=p_answers,version=version+1 where id=p_attempt;
 if p_action='submit' then perform private.esports_finish_attempt(a.id);else perform private.esports_audit('exam_saved',a.id);end if;
 return private.esports_safe_attempt(a.id);
 end;$function$

CREATE OR REPLACE FUNCTION public.esports_purge(p_user uuid DEFAULT NULL::uuid, p_confirmation text DEFAULT ''::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 declare ids uuid[];cnt integer;
 begin
 if not public.esports_is_admin() or p_confirmation<>'EXCLUIR DADOS ESPORTS' then raise exception 'Administrator and explicit confirmation required';end if;
 if p_user is not null and not exists(select 1 from private.esports_erasure_requests where user_id=p_user and status='requested') then raise exception 'Erasure request required';end if;
 select coalesce(array_agg(a.id),'{}') into ids from public.esports_applications a join public.esports_cycles c on c.id=a.cycle_id where (p_user is not null and a.user_id=p_user) or (p_user is null and not exists(select 1 from private.esports_role_grants r where r.application_id=a.id and r.role<>'applicant' and r.revoked_at is null and r.ends_at>now()) and not exists(select 1 from private.esports_scholarships ss where ss.application_id=a.id and ss.status in('offered','accepted') and ss.ends_at>now()) and now()>greatest(c.ends_at,a.updated_at)+make_interval(days=>coalesce((a.consent_snapshot->>'retention_days')::integer,c.retention_days)));
 -- Audit targets associated with erased records are removed; no candidate payload in audit.
 delete from private.esports_audit where target_id=any(ids) or target_id in(select id from private.esports_attempts where application_id=any(ids)) or target_id in(select id from private.esports_scholarships where application_id=any(ids));
 delete from private.esports_authorizations where (p_user is not null and user_id=p_user) or (revoked_at is not null and expires_at<now()-interval '30 days');
 delete from public.esports_applications where id=any(ids);get diagnostics cnt=row_count;
 if p_user is not null then
 delete from private.esports_role_grants where user_id=p_user;
 delete from private.esports_audit where actor_id=p_user or target_id=p_user or detail->>'user_id'=p_user::text;
 update private.esports_erasure_requests set status='handled',handled_at=now(),handled_by=auth.uid() where user_id=p_user;
 end if;
 perform private.esports_audit('retention_purge',null,jsonb_build_object('records',cnt));return cnt;
 end;$function$

CREATE OR REPLACE FUNCTION public.esports_request_erasure()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 insert into private.esports_erasure_requests(user_id) values(auth.uid()) on conflict(user_id) do update set status='requested',requested_at=now(),handled_at=null,handled_by=null;
 update public.esports_applications set status='withdrawn',version=version+1,updated_at=now() where user_id=auth.uid();
 update private.esports_role_grants set revoked_at=now() where user_id=auth.uid();
 update private.esports_benefit_grants set revoked_at=now() where user_id=auth.uid();
 perform private.esports_audit('erasure_requested',auth.uid());end;$function$

CREATE OR REPLACE FUNCTION public.esports_withdraw(p_application uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 perform 1 from public.esports_applications where id=p_application and user_id=auth.uid() for update;
 if not found then raise exception 'Application unavailable';end if;
 update public.esports_applications set status='withdrawn',version=version+1,updated_at=now() where id=p_application and status<>'withdrawn';
 update private.esports_role_grants set revoked_at=now() where application_id=p_application and revoked_at is null;
 insert into public.esports_status_events(application_id,status,message) values(p_application,'withdrawn','Participação retirada pelo candidato.');perform private.esports_audit('withdrawn',p_application);
 end;$function$

CREATE OR REPLACE FUNCTION private.esports_admin_action_internal(p_action text, p_id uuid DEFAULT NULL::uuid, p_expected integer DEFAULT 0, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 declare a public.esports_applications;c public.esports_cycles;u uuid;r text;expiry timestamptz;result jsonb:='{}';
 begin
 if auth.uid() is null or not(public.esports_is_admin() or private.esports_staff_access()) then raise exception 'Administrative role required';end if;
 if jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>30000 then raise exception 'Invalid administrative input';end if;
 if p_action in('note','practical','status') then
 select * into a from public.esports_applications where id=p_id for update;
 if not found or not public.esports_can_review(p_id) then raise exception 'Application unavailable';end if;
 if a.version<>p_expected then raise exception 'Version conflict';end if;
 if p_action in('note','practical') then
 insert into private.esports_reviews(application_id,actor_id,kind,note) values(p_id,auth.uid(),case when p_action='practical' then 'practical' else 'review' end,p_payload->>'note');
 else
 if not public.esports_is_admin() then raise exception 'Administrator decision required';end if;
 r:=p_payload->>'status';
 if not ((a.status='submitted' and r in('under_review','not_selected')) or (a.status='under_review' and r in('trial_invited','not_selected')) or (a.status='trial_invited' and r in('trial_in_progress','not_selected')) or (a.status='trial_in_progress' and r in('trial_completed','not_selected')) or (a.status='trial_completed' and r in('development_offered','academy_selected','not_selected','trial_invited')) or (a.status='development_offered' and r in('not_selected','trial_completed')) or (a.status='development_active' and r in('academy_selected','trial_completed','not_selected')) or (a.status='not_selected' and r='under_review')) then raise exception 'Invalid status transition';end if;
 if length(trim(coalesce(p_payload->>'message',''))) not between 3 and 2000 or length(trim(coalesce(p_payload->>'reason',''))) not between 3 and 1000 then raise exception 'Decision and reason required';end if;
 update public.esports_applications set status=r,version=version+1,updated_at=now() where id=p_id returning to_jsonb(esports_applications.*) into result;
 insert into public.esports_status_events(application_id,status,message) values(p_id,r,p_payload->>'message');
 if r='not_selected' then update private.esports_role_grants set revoked_at=now() where application_id=p_id and role='trialist' and revoked_at is null;end if;
 end if;
 else
 if not public.esports_is_admin() then raise exception 'Administrator required';end if;
 if p_action='settings' then
 if p_payload->>'recruitment_enabled'='true' and not exists(select 1 from private.esports_launch_gate where reviewed) then raise exception 'Launch review required';end if;
 update public.esports_settings set recruitment_enabled=(p_payload->>'recruitment_enabled')::boolean,official_discord=coalesce(p_payload->>'official_discord',''),introduction=p_payload->>'introduction',trial_intro=p_payload->>'trial_intro',support_text=p_payload->>'support_text',version=version+1,updated_at=now() where version=p_expected returning to_jsonb(esports_settings.*) into result;
 if result is null then raise exception 'Version conflict';end if;
 if length(result->>'introduction')>4000 or length(result->>'trial_intro')>8000 or length(result->>'support_text')>2000 then raise exception 'Invalid settings';end if;
 elsif p_action='cycle' then
 if p_payload->>'is_open'='true' and not exists(select 1 from private.esports_launch_gate where reviewed) then raise exception 'Launch review required';end if;
 if p_payload->>'allow_minors'='true' and not exists(select 1 from private.esports_launch_gate where minors_reviewed) then raise exception 'Minor protection review required';end if;
 if p_id is not null then select * into c from public.esports_cycles where id=p_id for update;if not found or c.version<>p_expected then raise exception 'Version conflict';end if;end if;
 insert into public.esports_cycles(id,title,mode,format,criteria,rules,privacy_notice,policy_version,retention_days,starts_at,ends_at,published,is_open,allow_minors)
 values(coalesce(p_id,gen_random_uuid()),p_payload->>'title',p_payload->>'mode',p_payload->>'format',p_payload->>'criteria',p_payload->>'rules',p_payload->>'privacy_notice',p_payload->>'policy_version',(p_payload->>'retention_days')::integer,(p_payload->>'starts_at')::timestamptz,(p_payload->>'ends_at')::timestamptz,(p_payload->>'published')::boolean,(p_payload->>'is_open')::boolean,(p_payload->>'allow_minors')::boolean)
 on conflict(id) do update set title=excluded.title,mode=excluded.mode,format=excluded.format,criteria=excluded.criteria,rules=excluded.rules,privacy_notice=excluded.privacy_notice,policy_version=excluded.policy_version,retention_days=excluded.retention_days,starts_at=excluded.starts_at,ends_at=excluded.ends_at,published=excluded.published,is_open=excluded.is_open,allow_minors=excluded.allow_minors,version=esports_cycles.version+1 returning to_jsonb(esports_cycles.*) into result;
 elsif p_action='grant_role' then
 u:=(p_payload->>'user_id')::uuid;r:=p_payload->>'role';expiry:=(p_payload->>'ends_at')::timestamptz;
 if u=auth.uid() or expiry<=now() or expiry>now()+interval '2 years' then raise exception 'Invalid grant or self assignment';end if;
 if r in('esports_admin','esports_staff') and not public.is_admin() then raise exception 'Platform administrator required';end if;
 if r in('applicant','development_scholar','academy_player','roster_player') then raise exception 'Use explicit scholarship or roster decision';end if;
 if r='trialist' and not exists(select 1 from public.esports_applications where id=p_id and user_id=u and status in('trial_invited','trial_in_progress','trial_completed')) then raise exception 'Trial invitation required';end if;
 insert into private.esports_role_grants(user_id,application_id,role,ends_at,granted_by,reason) values(u,case when r in('applicant','trialist') then p_id else null end,r,expiry,auth.uid(),p_payload->>'reason') returning jsonb_build_object('id',id) into result;
 elsif p_action='revoke_role' then
 perform 1 from private.esports_role_grants where id=p_id and (role not in('esports_admin','esports_staff') or public.is_admin()) for update;if not found then raise exception 'Grant unavailable';end if;
 if length(trim(coalesce(p_payload->>'reason',''))) not between 3 and 1000 then raise exception 'Reason required';end if;
 update private.esports_role_grants set revoked_at=now() where id=p_id;
 elsif p_action='assign_reviewer' then
 u:=(p_payload->>'user_id')::uuid;
 if not private.esports_role('esports_staff',u) or not exists(select 1 from public.esports_applications where id=p_id) then raise exception 'Active staff and application required';end if;
 if p_payload->>'revoke'='true' then delete from private.esports_reviewers where application_id=p_id and user_id=u;else insert into private.esports_reviewers values(p_id,u) on conflict do nothing;end if;
 elsif p_action='authorization' then
 if not exists(select 1 from private.esports_launch_gate where minors_reviewed) then raise exception 'Minor protection review required';end if;
 u:=(p_payload->>'user_id')::uuid;expiry:=(p_payload->>'expires_at')::timestamptz;
 if expiry<=now() then raise exception 'Invalid authorization expiry';end if;
 insert into private.esports_authorizations(user_id,cycle_id,verified_by,expires_at,policy_version,reference) values(u,p_id,auth.uid(),expiry,p_payload->>'policy_version',p_payload->>'reference') on conflict(user_id,cycle_id) do update set verified_by=auth.uid(),verified_at=now(),expires_at=excluded.expires_at,policy_version=excluded.policy_version,reference=excluded.reference,revoked_at=null;
 elsif p_action='revoke_authorization' then
 update private.esports_authorizations set revoked_at=now() where user_id=(p_payload->>'user_id')::uuid and cycle_id=p_id;
 else raise exception 'Unknown administrative action';end if;
 end if;
 perform private.esports_audit(p_action,coalesce(p_id,case when result->>'id' ~ '^[0-9a-f-]{36}$' then (result->>'id')::uuid else null end),p_payload);return coalesce(result,'{}');
 end;$function$

CREATE OR REPLACE FUNCTION private.esports_assessment_action_internal(p_action text, p_id uuid DEFAULT NULL::uuid, p_expected integer DEFAULT 0, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 declare q private.esports_questions;e private.esports_exams;a private.esports_attempts;result jsonb;slot jsonb;x jsonb;k record;total integer:=0;seen text[]:='{}';ref jsonb;
 begin
 if auth.uid() is null or not(public.esports_is_admin() or private.esports_staff_access()) then raise exception 'Administrative role required';end if;
 if jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>100000 then raise exception 'Invalid assessment input';end if;
 if p_action='grade' then
 select * into a from private.esports_attempts where id=p_id for update;
 if not found or a.status='active' or not public.esports_can_review(a.application_id) then raise exception 'Submitted attempt unavailable';end if;
 if a.version<>p_expected then raise exception 'Version conflict';end if;
 if length(coalesce(p_payload->>'review_note','')) not between 3 and 8000 or length(coalesce(p_payload->>'feedback',''))>8000 or jsonb_typeof(p_payload->'grades') is distinct from 'object' then raise exception 'Review required';end if;
 for k in select * from jsonb_each(p_payload->'grades') loop
 select value into x from jsonb_array_elements(a.questions) where value->>'id'=k.key and value->>'kind'='discursive';
 if not found or jsonb_typeof(k.value) is distinct from 'number' or k.value::text::numeric<0 or k.value::text::numeric>(x->>'weight')::numeric then raise exception 'Invalid manual grade';end if;end loop;
 if exists(select 1 from jsonb_array_elements(a.questions) item where item->>'kind'='discursive' and not (p_payload->'grades' ? (item->>'id'))) then raise exception 'Grade each discursive question';end if;
 insert into private.esports_attempt_reviews(attempt_id,reviewer_id,attempt_version,grades,review_note,feedback,released) values(a.id,auth.uid(),a.version,p_payload->'grades',p_payload->>'review_note',coalesce(p_payload->>'feedback',''),coalesce((p_payload->>'released')::boolean,false));
 update private.esports_attempts set status='graded',version=version+1,manual_grades=p_payload->'grades',reviewer_id=auth.uid(),review_note=p_payload->>'review_note',feedback=coalesce(p_payload->>'feedback',''),released=coalesce((p_payload->>'released')::boolean,false) where id=p_id;
 elsif public.esports_is_admin() then
 if p_action='question' then
 if p_id is not null then select * into q from private.esports_questions where id=p_id for update;if not found or q.version<>p_expected then raise exception 'Version conflict';end if;end if;
 if (p_payload->>'reviewed_at')::timestamptz>now() or (p_payload->>'reviewed_at')::timestamptz<now()-interval '2 years' then raise exception 'Invalid review date';end if;
 if jsonb_typeof(p_payload->'references_list') is distinct from 'array' or jsonb_typeof(p_payload->'options') is distinct from 'array' then raise exception 'References and options required';end if;
 for ref in select value from jsonb_array_elements(p_payload->'references_list') loop
 if jsonb_typeof(ref) is distinct from 'string' or length(ref#>>'{}')>500 or (ref#>>'{}') !~ '^(https://[A-Za-z0-9][^[:space:]]*|/academy/[^[:space:]]+)$' then raise exception 'Invalid source reference';end if;end loop;
 for ref in select value from jsonb_array_elements(p_payload->'options') loop
 if jsonb_typeof(ref) is distinct from 'string' or length(trim(ref#>>'{}')) not between 1 and 1000 then raise exception 'Invalid answer option';end if;end loop;
 insert into private.esports_questions(id,category,difficulty,kind,prompt,options,correct,explanation,references_list,weight,published,reviewed_at) values(coalesce(p_id,gen_random_uuid()),p_payload->>'category',p_payload->>'difficulty',p_payload->>'kind',p_payload->>'prompt',p_payload->'options',(p_payload->>'correct')::integer,p_payload->>'explanation',p_payload->'references_list',(p_payload->>'weight')::numeric,coalesce((p_payload->>'published')::boolean,false),(p_payload->>'reviewed_at')::timestamptz)
 on conflict(id) do update set category=excluded.category,difficulty=excluded.difficulty,kind=excluded.kind,prompt=excluded.prompt,options=excluded.options,correct=excluded.correct,explanation=excluded.explanation,references_list=excluded.references_list,weight=excluded.weight,published=excluded.published,reviewed_at=excluded.reviewed_at,version=esports_questions.version+1 returning to_jsonb(esports_questions.*) into result;
 elsif p_action='exam' then
 if p_id is not null then select * into e from private.esports_exams where id=p_id for update;if not found or e.version<>p_expected then raise exception 'Version conflict';end if;end if;
 if jsonb_typeof(p_payload->'blueprint') is distinct from 'array' then raise exception 'Balanced blueprint required';end if;
 for slot in select value from jsonb_array_elements(p_payload->'blueprint') loop
 if length(coalesce(slot->>'category','')) not between 2 and 80 or coalesce(slot->>'difficulty','') not in('foundation','intermediate','advanced') or coalesce(slot->>'count','') !~ '^[0-9]{1,2}$' then raise exception 'Invalid blueprint';end if;
 if (slot->>'count')::integer not between 1 and 40 or ((slot->>'category')||'/'||(slot->>'difficulty'))=any(seen) then raise exception 'Duplicate or invalid blueprint slot';end if;
 seen:=array_append(seen,(slot->>'category')||'/'||(slot->>'difficulty'));total:=total+(slot->>'count')::integer;end loop;
 if total not between 1 and 40 then raise exception 'Invalid exam size';end if;
 insert into private.esports_exams(id,title,instructions,rules,blueprint,minutes,max_attempts,published) values(coalesce(p_id,gen_random_uuid()),p_payload->>'title',p_payload->>'instructions',p_payload->>'rules',p_payload->'blueprint',(p_payload->>'minutes')::integer,(p_payload->>'max_attempts')::integer,coalesce((p_payload->>'published')::boolean,false)) on conflict(id) do update set title=excluded.title,instructions=excluded.instructions,rules=excluded.rules,blueprint=excluded.blueprint,minutes=excluded.minutes,max_attempts=excluded.max_attempts,published=excluded.published,version=esports_exams.version+1 returning to_jsonb(esports_exams.*) into result;
 elsif p_action='assign' then
 if not exists(select 1 from public.esports_applications where id=p_id and status in('trial_invited','trial_in_progress','trial_completed')) then raise exception 'Trial invitation required';end if;
 if (p_payload->>'available_until')::timestamptz<=now() then raise exception 'Invalid exam deadline';end if;
 insert into private.esports_exam_assignments(application_id,exam_id,available_until) values(p_id,(p_payload->>'exam_id')::uuid,(p_payload->>'available_until')::timestamptz) on conflict(application_id,exam_id) do update set available_until=excluded.available_until,revoked_at=null;
 elsif p_action='extra_attempt' then
 if length(coalesce(p_payload->>'reason','')) not between 3 and 1000 then raise exception 'Exception reason required';end if;
 update private.esports_exam_assignments set extra_attempts=extra_attempts+1 where application_id=p_id and exam_id=(p_payload->>'exam_id')::uuid and extra_attempts<5;if not found then raise exception 'Assignment unavailable';end if;
 elsif p_action='revoke_assignment' then
 update private.esports_exam_assignments set revoked_at=now() where application_id=p_id and exam_id=(p_payload->>'exam_id')::uuid;
 else raise exception 'Unknown assessment action';end if;
 else raise exception 'Administrator required';end if;
 -- Answers/content are kept in protected versioned rows, audit only identifies operation.
 perform private.esports_audit('assessment_'||p_action,coalesce(p_id,(result->>'id')::uuid));return coalesce(result,'{}');
 end;$function$

CREATE OR REPLACE FUNCTION private.esports_development_action_internal(p_action text, p_id uuid DEFAULT NULL::uuid, p_expected integer DEFAULT 0, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 declare s private.esports_scholarships;g private.esports_development_goals;a public.esports_applications;benefit jsonb;result jsonb;expiry timestamptz;start_at timestamptz;u uuid;
 begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 if jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>30000 then raise exception 'Invalid development input';end if;
 if p_action in('accept','decline') then
 select * into s from private.esports_scholarships where id=p_id for update;
 if not found or s.user_id<>auth.uid() or not private.esports_participation(s.application_id) then raise exception 'Offer unavailable';end if;
 if p_action='accept' and s.status='accepted' then return jsonb_build_object('id',s.id);end if;
 if s.version<>p_expected then raise exception 'Version conflict';end if;
 if s.status<>'offered' or s.ends_at<=now() then raise exception 'Offer unavailable';end if;
 if p_action='accept' then
 if p_payload->>'accepted' is distinct from 'true' then raise exception 'Explicit acceptance required';end if;
 update private.esports_scholarships set status='accepted',version=version+1,accepted_at=now(),accepted_snapshot=jsonb_build_object('terms',s.terms,'benefits',s.benefits,'human_availability',s.human_availability,'starts_at',s.starts_at,'ends_at',s.ends_at,'version',s.version) where id=p_id;
 insert into private.esports_role_grants(user_id,application_id,role,starts_at,ends_at,granted_by,reason) values(auth.uid(),s.application_id,'development_scholar',greatest(s.starts_at,now()),s.ends_at,s.offered_by,'Bolsa aceita expressamente');
 for benefit in select value from jsonb_array_elements(s.benefits) loop insert into private.esports_benefit_grants(user_id,scholarship_id,capability,starts_at,ends_at) values(auth.uid(),s.id,benefit#>>'{}',s.starts_at,s.ends_at);end loop;
 update public.esports_applications set status='development_active',version=version+1,updated_at=now() where id=s.application_id;
 insert into public.esports_status_events(application_id,status,message) values(s.application_id,'development_active','Bolsa de desenvolvimento aceita. Não representa ingresso no elenco.');
 else update private.esports_scholarships set status='declined',version=version+1 where id=p_id;update public.esports_applications set status='trial_completed',version=version+1,updated_at=now() where id=s.application_id;end if;
 elsif p_action='progress' then
 select * into g from private.esports_development_goals where id=p_id for update;
 if not found or not private.esports_scholar(g.scholarship_id) then raise exception 'Goal unavailable';end if;
 if g.version<>p_expected then raise exception 'Version conflict';end if;
 update private.esports_development_goals set state=p_payload->>'state',learner_note=coalesce(p_payload->>'learner_note',''),version=version+1 where id=p_id;
 elsif public.esports_is_admin() or private.esports_staff_access() then
 if p_action in('goal','review') then
 select * into s from private.esports_scholarships where id=(p_payload->>'scholarship_id')::uuid for share;
 if not found or not public.esports_can_review(s.application_id) then raise exception 'Scholarship unavailable';end if;
 if p_action='goal' then
 if p_id is not null then select * into g from private.esports_development_goals where id=p_id for update;if not found or g.scholarship_id<>s.id or g.version<>p_expected then raise exception 'Version conflict';end if;end if;
 insert into private.esports_development_goals(id,scholarship_id,title,description,kind,due_at,route) values(coalesce(p_id,gen_random_uuid()),s.id,p_payload->>'title',p_payload->>'description',p_payload->>'kind',(p_payload->>'due_at')::timestamptz,coalesce(p_payload->>'route','')) on conflict(id) do update set title=excluded.title,description=excluded.description,kind=excluded.kind,due_at=excluded.due_at,route=excluded.route,version=esports_development_goals.version+1 returning jsonb_build_object('id',id) into result;
 else insert into private.esports_development_reviews(scholarship_id,reviewer_id,shared_feedback,internal_note,next_step) values(s.id,auth.uid(),p_payload->>'shared_feedback',p_payload->>'internal_note',p_payload->>'next_step') returning jsonb_build_object('id',id) into result;end if;
 else
 if not public.esports_is_admin() then raise exception 'Administrator required';end if;
 if p_action='offer' then
 select * into a from public.esports_applications where id=p_id for update;
 if not found or a.user_id=auth.uid() or a.status<>'trial_completed' or a.version<>p_expected then raise exception 'Completed human evaluation required';end if;
 if not exists(select 1 from private.esports_reviews where application_id=a.id and kind='practical') then raise exception 'Practical review required';end if;
 start_at:=(p_payload->>'starts_at')::timestamptz;expiry:=(p_payload->>'ends_at')::timestamptz;
 if expiry<=now() or expiry>now()+interval '2 years' or start_at<now()-interval '1 day' then raise exception 'Invalid scholarship period';end if;
 if jsonb_typeof(p_payload->'benefits') is distinct from 'array' then raise exception 'Benefits required';end if;
 for benefit in select value from jsonb_array_elements(p_payload->'benefits') loop
 if jsonb_typeof(benefit) is distinct from 'string' or (benefit#>>'{}') not in('plan_tools','materials','periodic_review','development_workspace','human_feedback') then raise exception 'Unavailable benefit: Pro/commercial resources are not activated';end if;
 if benefit#>>'{}'='human_feedback' and length(trim(coalesce(p_payload->>'human_availability',''))) not between 10 and 2000 then raise exception 'Human feedback availability required';end if;end loop;
 insert into private.esports_scholarships(application_id,user_id,title,terms,benefits,human_availability,starts_at,ends_at,offered_by) values(a.id,a.user_id,p_payload->>'title',p_payload->>'terms',p_payload->'benefits',coalesce(p_payload->>'human_availability',''),start_at,expiry,auth.uid()) returning jsonb_build_object('id',id) into result;
 update public.esports_applications set status='development_offered',version=version+1,updated_at=now() where id=a.id;
 insert into public.esports_status_events(application_id,status,message) values(a.id,'development_offered','Uma bolsa temporária foi oferecida. Leia as condições no espaço de desenvolvimento.');
 elsif p_action in('revoke','end','extend') then
 select * into s from private.esports_scholarships where id=p_id for update;if not found or s.version<>p_expected then raise exception 'Version conflict';end if;
 if length(coalesce(p_payload->>'reason','')) not between 3 and 1000 then raise exception 'Reason required';end if;
 if p_action='extend' then
 expiry:=(p_payload->>'ends_at')::timestamptz;
 if s.status<>'accepted' or s.ends_at<=now() or expiry<=s.ends_at or expiry>now()+interval '2 years' then raise exception 'Active scholarship and later expiry required';end if;
 update private.esports_scholarships set ends_at=expiry,version=version+1 where id=s.id;
 update private.esports_benefit_grants set ends_at=expiry where scholarship_id=s.id and revoked_at is null;
 update private.esports_role_grants set ends_at=expiry where application_id=s.application_id and role='development_scholar' and revoked_at is null;
 else
 update private.esports_scholarships set status=case when p_action='end' then 'ended' else 'revoked' end,version=version+1 where id=s.id;
 update private.esports_benefit_grants set revoked_at=now() where scholarship_id=s.id;
 update private.esports_role_grants set revoked_at=now() where application_id=s.application_id and role='development_scholar' and revoked_at is null;
 update public.esports_applications set status='trial_completed',version=version+1,updated_at=now() where id=s.application_id and status in('development_active','development_offered');
 insert into public.esports_status_events(application_id,status,message) values(s.application_id,'trial_completed','Bolsa encerrada ou revogada. Assinaturas pessoais não são alteradas.');end if;
 elsif p_action='roster_decision' then
 select * into a from public.esports_applications where id=p_id for update;
 if not found or a.user_id=auth.uid() or a.version<>p_expected or a.status not in('trial_completed','development_active') then raise exception 'Explicit reviewed decision required';end if;
 if p_payload->>'kind'='roster_player' then raise exception 'Professional roster requires a separate formalization workflow, not available';end if;
 if p_payload->>'kind' is distinct from 'academy_player' or p_payload->>'requirements_confirmed' is distinct from 'true' or not exists(select 1 from private.esports_launch_gate where roster_reviewed) then raise exception 'Roster requirements review required';end if;
 expiry:=(p_payload->>'ends_at')::timestamptz;if expiry<=now() or expiry>now()+interval '2 years' then raise exception 'Invalid roster period';end if;
 insert into private.esports_roster_decisions(application_id,kind,actor_id,reason,formalization_reference) values(a.id,'academy_player',auth.uid(),p_payload->>'reason',p_payload->>'formalization_reference');
 insert into private.esports_role_grants(user_id,application_id,role,ends_at,granted_by,reason) values(a.user_id,a.id,'academy_player',expiry,auth.uid(),p_payload->>'reason');
 update public.esports_applications set status='academy_selected',version=version+1,updated_at=now() where id=a.id;
 insert into public.esports_status_events(application_id,status,message) values(a.id,'academy_selected','Seleção expressa para Academy Roster registrada. Publicação de dados depende de autorização própria.');
 else raise exception 'Unknown development action';end if;
 end if;
 else raise exception 'Administrative role required';end if;
 perform private.esports_audit('development_'||p_action,coalesce(p_id,(result->>'id')::uuid),case when p_action in('revoke','end','extend','roster_decision') then jsonb_build_object('reason',p_payload->>'reason') else '{}'::jsonb end);
 return coalesce(result,'{}');
 end;$function$

CREATE OR REPLACE FUNCTION public.publish_meta_draft(p_id uuid, p_expected integer, p_withdraw boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.meta_drafts;p jsonb;prev public.meta_entries;e text;v jsonb;begin
 perform private.meta_editor_gate();
 select * into d from public.meta_drafts where id=p_id for update;
 if not found or d.version<>p_expected then raise exception 'Draft changed; reload before publishing';end if;
 if (not p_withdraw and d.status<>'review') or (p_withdraw and (d.published_entry_id is null or d.status<>'published')) then raise exception 'Review or previous publication required';end if;
 p=d.payload;perform private.validate_meta_content(p);
 -- Serialize the entire read/build/insert chain, not just the final INSERT.
 lock table public.meta_entries in share row exclusive mode;
 select * into prev from public.meta_entries where subject_key=p->>'subject_key' and context_id=p->>'context_id' order by revision desc limit 1;
 if d.published_entry_id is distinct from prev.id then raise exception 'Publication changed; create revision from the latest edition';end if;
 if exists(select 1 from public.meta_editions ed join public.meta_entries me on me.id=ed.entry_id where me.context_id=p->>'context_id' and ed.content->>'slug'=p->>'slug' and me.subject_key<>p->>'subject_key') then raise exception 'Slug already used in this context';end if;
 e='meta-'||gen_random_uuid()::text;
 insert into public.meta_entries(id,subject_key,context_id,revision,previous_id,kind,title,category,body,state,availability,evidence,source_ids,verified_at,valid_from,review_due,limitations,change_note)
 values(e,p->>'subject_key',p->>'context_id',coalesce(prev.revision,0)+1,prev.id,p->>'kind',p->>'title',p->>'category',p->>'body',case when p_withdraw then 'archived' else p->>'state' end,p->>'availability',p->>'evidence',array(select jsonb_array_elements_text(p->'source_ids')),(p->>'verified_at')::timestamptz,clock_timestamp(),(p->>'review_due')::timestamptz,p->>'limitations',p->>'change_note');
 if not p_withdraw then
  insert into public.meta_editions(entry_id,content) values(e,p);
  for v in select value from jsonb_array_elements(p->'links') loop insert into public.meta_links values('link-'||gen_random_uuid()::text,e,v->>'target_kind',v->>'target_id',v->>'reason');end loop;
 end if;
 update public.meta_drafts set published_entry_id=e,status=case when p_withdraw then 'archived' else 'published' end,version=version+1,editor_id=auth.uid(),updated_at=clock_timestamp() where id=p_id returning * into d;
 insert into public.meta_draft_history(draft_id,payload,version,status,actor_id) values(d.id,d.payload,d.version,d.status,auth.uid());return e;
end;$function$

CREATE OR REPLACE FUNCTION public.save_meta_draft(p_payload jsonb, p_status text, p_id uuid DEFAULT NULL::uuid, p_expected integer DEFAULT 0)
 RETURNS meta_drafts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.meta_drafts;begin
 perform private.meta_editor_gate();perform private.validate_meta_content(p_payload,p_status='review');
 if p_status not in ('draft','review') then raise exception 'Invalid workflow transition';end if;
 if p_id is null then
  insert into public.meta_drafts(payload,status,editor_id,published_entry_id) values(p_payload,p_status,auth.uid(),(select id from public.meta_entries where subject_key=p_payload->>'subject_key' and context_id=p_payload->>'context_id' order by revision desc limit 1)) returning * into d;
 else
  select * into d from public.meta_drafts where id=p_id for update;
  if not found or d.version<>p_expected then raise exception 'Draft changed; reload before saving';end if;
  if d.payload->>'subject_key'<>p_payload->>'subject_key' or d.payload->>'context_id'<>p_payload->>'context_id' then raise exception 'Stable identity cannot change; create another context edition';end if;
  update public.meta_drafts set payload=p_payload,status=p_status,editor_id=auth.uid(),version=version+1,updated_at=clock_timestamp() where id=p_id returning * into d;
 end if;
 insert into public.meta_draft_history(draft_id,payload,version,status,actor_id) values(d.id,d.payload,d.version,d.status,auth.uid());return d;
end;$function$

CREATE OR REPLACE FUNCTION public.esports_admin_action(p_action text, p_id uuid DEFAULT NULL::uuid, p_expected integer DEFAULT 0, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 declare result jsonb;
 begin
 perform private.esports_write_limit();
 if p_action='status' and (p_payload->>'status' in('development_offered','development_active','academy_selected') or exists(select 1 from private.esports_scholarships where application_id=p_id and status in('offered','accepted') and ends_at>now()) and p_payload->>'status'='trial_completed') then raise exception 'Use explicit scholarship or roster workflow';end if;
 result:=private.esports_admin_action_internal(p_action,p_id,p_expected,p_payload);
 if p_action='status' and p_payload->>'status'='not_selected' then
 update private.esports_role_grants set revoked_at=now() where application_id=p_id and revoked_at is null;
 update private.esports_benefit_grants set revoked_at=now() where scholarship_id in(select id from private.esports_scholarships where application_id=p_id);
 update private.esports_scholarships set status='revoked',version=version+1 where application_id=p_id and status in('offered','accepted');
 end if;
 if p_action='revoke_authorization' then
 update private.esports_role_grants r set revoked_at=now() from public.esports_applications a where r.application_id=a.id and a.cycle_id=p_id and a.user_id=(p_payload->>'user_id')::uuid and a.payload->>'age_band'='adolescent' and r.revoked_at is null;
 update private.esports_benefit_grants set revoked_at=now() where scholarship_id in(select s.id from private.esports_scholarships s join public.esports_applications a on a.id=s.application_id where a.cycle_id=p_id and a.user_id=(p_payload->>'user_id')::uuid and a.payload->>'age_band'='adolescent');
 end if;
 return result;
 end;$function$

CREATE OR REPLACE FUNCTION public.esports_start_exam(p_application uuid, p_exam uuid, p_accepted boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 declare e private.esports_exams;x private.esports_exam_assignments;a uuid;seed_value uuid:=gen_random_uuid();slot jsonb;q record;qs jsonb:='[]';n integer;selected integer;total integer:=0;
 begin
 perform 1 from public.esports_applications where id=p_application for update;
 if p_accepted is distinct from true or not private.esports_trial(p_application) then raise exception 'Active Trialist and acceptance required';end if;
 select * into x from private.esports_exam_assignments where application_id=p_application and exam_id=p_exam and revoked_at is null;
 if not found or x.available_until<=now() then raise exception 'Exam unavailable';end if;
 select * into e from private.esports_exams where id=p_exam and published;if not found then raise exception 'Exam unavailable';end if;
 select id into a from private.esports_attempts where application_id=p_application and exam_id=p_exam and status='active';if found then return private.esports_safe_attempt(a);end if;
 select count(*) into n from private.esports_attempts where application_id=p_application and exam_id=p_exam;
 if n>=e.max_attempts+x.extra_attempts then raise exception 'Attempt limit';end if;
 for slot in select value from jsonb_array_elements(e.blueprint) loop
 selected:=0;
 for q in select * from private.esports_questions where published and category=slot->>'category' and difficulty=slot->>'difficulty' order by md5(seed_value::text||id::text) limit (slot->>'count')::integer loop
 qs:=qs||jsonb_build_array(to_jsonb(q)-'published'-'reviewed_at');selected:=selected+1;end loop;
 if selected<>(slot->>'count')::integer then raise exception 'Insufficient reviewed questions';end if;total:=total+selected;
 end loop;
 if total<1 or total>40 then raise exception 'Invalid exam size';end if;
 insert into private.esports_attempts(application_id,exam_id,user_id,number,seed,exam_snapshot,questions,deadline) values(p_application,p_exam,auth.uid(),n+1,seed_value,jsonb_build_object('title',e.title,'version',e.version,'instructions',e.instructions,'rules',e.rules,'minutes',e.minutes,'blueprint',e.blueprint,'selection_algorithm','md5(seed UUID + question UUID), ascending per category/difficulty; frozen snapshot v1'),qs,least(now()+make_interval(mins=>e.minutes),x.available_until)) returning id into a;
 perform private.esports_audit('exam_started',a);return private.esports_safe_attempt(a);
 end;$function$

CREATE OR REPLACE FUNCTION public.esports_expire_assessments()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare expired record; completed integer:=0; remaining integer;
begin
 if auth.uid() is null or not(public.esports_is_admin() or private.esports_staff_access()) then
  raise exception 'Administrative role required';
 end if;
 -- The shared quota serializes on the caller's profile row; require that row.
 perform 1 from public.profiles where id=auth.uid() for update;
 if not found then
  raise exception 'Profile required';
 end if;
 perform private.esports_write_limit();
 select greatest(0,120-count(*))::integer into remaining from private.esports_audit
  where actor_id=auth.uid() and created_at>now()-interval '1 minute';
 for expired in select id from private.esports_attempts where status='active' and deadline<=now()
   and public.esports_can_review(application_id) order by deadline,id limit least(25,remaining)
   for update skip locked loop
  perform private.esports_finish_attempt(expired.id);
  completed:=completed+1;
 end loop;
 return completed;
end;$function$
